using System.Globalization;
using System.Linq;
using System.Text.RegularExpressions;

static class Str {
  public static readonly string[] Codes = { "en", "zh", "es", "ar", "pt", "id", "fr", "ja", "ru", "de" };
  public static readonly string[] Names = { "English", "中文", "Español", "العربية", "Português", "Bahasa Indonesia", "Français", "日本語", "Русский", "Deutsch" };
  static int L = Index(CultureInfo.CurrentUICulture.TwoLetterISOLanguageName);

  public static int Index(string code) {
    if (string.IsNullOrEmpty(code)) return 0;
    var i = Array.IndexOf(Codes, (code.Length > 2 ? code.Substring(0, 2) : code).ToLowerInvariant());
    return i < 0 ? 0 : i;
  }
  public static int Cur { get { return L; } set { L = value; } }
  public static bool Rtl { get { return Codes[L] == "ar"; } }
  public static bool Has(string k) { return S.ContainsKey(k); }
  public static string T(string k, params object[] a) { var s = S[k][L]; return a.Length == 0 ? s : string.Format(s, a); }

  // null = всё в порядке, иначе список проблем (по одной на строку)
  public static string Check() {
    var bad = new List<string>();
    foreach (var kv in S) {
      if (kv.Value.Length != Codes.Length) { bad.Add(kv.Key + ": " + kv.Value.Length + " вместо " + Codes.Length); continue; }
      var ph = Placeholders(kv.Value[0]);
      for (int i = 0; i < Codes.Length; i++) {
        if (string.IsNullOrWhiteSpace(kv.Value[i])) bad.Add(kv.Key + ": нет перевода " + Codes[i]);
        else if (Placeholders(kv.Value[i]) != ph) bad.Add(kv.Key + ": в " + Codes[i] + " не совпадают {0}");
      }
    }
    return bad.Count == 0 ? null : string.Join("\n", bad);
  }
  public static int Count { get { return S.Count; } }
  static string Placeholders(string s) { return string.Join(",", Regex.Matches(s ?? "", @"\{\d+\}").Cast<Match>().Select(m => m.Value).OrderBy(x => x)); }

  static string[] A(params string[] v) { return v; }

